1	/**
2	 * PearlOS Visual Regression Test Harness
3	 *
4	 * Provides helpers for Playwright tests that invoke PearlOS tools via the
5	 * gateway REST API, take screenshots, and capture console output.
6	 */
7	
8	import { Page } from '@playwright/test';
9	import * as fs from 'fs';
10	import * as path from 'path';
11	
12	const GATEWAY_URL = process.env.GATEWAY_URL || 'http://localhost:4444';
13	const SCREENSHOTS_DIR = path.resolve(__dirname, 'screenshots');
14	
15	// Ensure screenshots directory exists
16	fs.mkdirSync(SCREENSHOTS_DIR, { recursive: true });
17	
18	export interface ToolResult {
19	  screenshot: Buffer;
20	  consoleLogs: string[];
21	  consoleErrors: string[];
22	  timestamp: Date;
23	  toolName: string;
24	  httpStatus: number;
25	  responseBody: any;
26	  screenshotPath: string;
27	}
28	
29	export interface TestReport {
30	  testName: string;
31	  results: ToolResult[];
32	  passed: boolean;
33	  error?: string;
34	  durationMs: number;
35	}
36	
37	const _reports: TestReport[] = [];
38	
39	/** Collect console messages from page */
40	export function setupConsoleCapture(page: Page) {
41	  const logs: string[] = [];
42	  const errors: string[] = [];
43	  page.on('console', (msg) => {
44	    const text = `[${msg.type()}] ${msg.text()}`;
45	    logs.push(text);
46	    if (msg.type() === 'error') errors.push(text);
47	  });
48	  page.on('pageerror', (err) => {
49	    errors.push(`[pageerror] ${err.message}`);
50	  });
51	  return { logs, errors };
52	}
53	
54	/** Navigate to PearlOS and wait for the Stage component */
55	export async function loadPearlOS(page: Page) {
56	  await page.goto('/pearlos', { waitUntil: 'networkidle', timeout: 30_000 });
57	  // Wait for the Stage/app root to appear
58	  await page.waitForSelector('#root, [data-testid="stage"], .stage, main', {
59	    timeout: 15_000,
60	  }).catch(() => {
61	    // If none of the specific selectors match, just wait for body content
62	    return page.waitForSelector('body', { timeout: 5_000 });
63	  });
64	  // Extra settle time for React hydration
65	  await page.waitForTimeout(2000);
66	}
