13	 *   - Full event bus integrity
14	 *
15	 * Tests run on both desktop (1440×900) and iOS mobile (390×844) viewports.
16	 *
17	 * Run:
18	 *   npx playwright test tests/e2e/wonder-canvas-delivery.test.ts \
19	 *     --config tests/e2e/playwright.config.ts
20	 *
21	 * Relay mode (pearlos-tool invoke through WS):
22	 *   PEARLOS_RELAY=1 npx playwright test tests/e2e/wonder-canvas-delivery.test.ts \
23	 *     --config tests/e2e/playwright.config.ts
24	 */
25	
26	import { test, expect, type Page } from '@playwright/test';
27	import { execSync } from 'child_process';
28	
