40	async function dispatchNia(page: Page, name: string, payload: Record<string, unknown> = {}) {
41	  await page.evaluate(({ name, payload }) => {
42	    window.dispatchEvent(new CustomEvent(name, { detail: { payload } }));
43	  }, { name, payload });
44	}
45	
46	/** Post a message directly to the Wonder Canvas iframe runtime */
47	async function postToIframe(page: Page, msg: Record<string, unknown>) {
48	  await page.evaluate((m) => {
49	    const iframe = document.querySelector('[data-testid="wonder-canvas"] iframe') as HTMLIFrameElement | null;
50	    iframe?.contentWindow?.postMessage(m, '*');
51	  }, msg);
52	}
