54	/** Query something inside the wonder canvas iframe */
55	async function queryIframe<T>(page: Page, fn: string): Promise<T> {
56	  return page.evaluate((fnStr) => {
57	    const iframe = document.querySelector('[data-testid="wonder-canvas"] iframe') as HTMLIFrameElement;
58	    const doc = iframe?.contentDocument;
59	    if (!doc) throw new Error('Cannot access iframe contentDocument');
60	    return new Function('doc', `return (${fnStr})(doc)`)(doc);
61	  }, fn) as Promise<T>;
62	}
63	
64	/** Wait for an element to appear inside the wonder iframe */
65	async function waitForInIframe(page: Page, selector: string, timeoutMs = 5000) {
66	  const deadline = Date.now() + timeoutMs;
67	  while (Date.now() < deadline) {
68	    const found = await page.evaluate(({ sel }) => {
69	      const iframe = document.querySelector('[data-testid="wonder-canvas"] iframe') as HTMLIFrameElement;
70	      return !!iframe?.contentDocument?.querySelector(sel);
71	    }, { sel: selector });
72	    if (found) return;
73	    await page.waitForTimeout(200);
74	  }
75	  throw new Error(`Timeout: "${selector}" not found in wonder iframe after ${timeoutMs}ms`);
76	}
