3	 * 
4	 * Secure, flexible, and testable credential management for all data sources.
5	 * Supports environment variables, secret providers, and runtime registration.
6	 */
7	import { getLogger } from '../core/logger';
8	const log = getLogger('prism:data:credentials');
9	
10	export interface DataSourceCredentials {
11	  type: 'postgres' | 'mongodb' | 'mysql' | 'openapi' | 'graphql';
12	  host?: string;
13	  port?: number;
14	  database?: string;
15	  username?: string;
16	  password?: string;
17	  connectionString?: string;
18	  schema?: string;
19	  ssl?: boolean;
20	  // API-specific fields
21	  baseUrl?: string;
22	  apiKey?: string;
23	  bearerToken?: string;
24	  // Secret references
25	  secretRef?: string;
26	  passwordSecretRef?: string;
27	  apiKeySecretRef?: string;
28	  tokenSecretRef?: string;
29	  // Additional configuration
30	  [key: string]: any;
31	}
32	
33	export interface SecretProvider {
34	  name: string;
35	  resolve(secretRef: string): Promise<string>;
36	}
37	
38	export interface CredentialResolverOptions {
39	  providers?: SecretProvider[];
40	  allowEnvironmentFallback?: boolean;
41	  logSecretAccess?: boolean;
42	}
43	
