45	 * Secure credential resolution with support for multiple providers
46	 */
47	export class CredentialResolver {
48	  private providers: SecretProvider[] = [];
49	  private allowEnvironmentFallback: boolean = true;
50	  private logSecretAccess: boolean = false;
51	
52	  constructor(options: CredentialResolverOptions = {}) {
53	    this.providers = options.providers || [];
54	    this.allowEnvironmentFallback = options.allowEnvironmentFallback ?? true;
55	    this.logSecretAccess = options.logSecretAccess ?? false;
56	  }
57	
58	  /**
59	   * Add a secret provider
60	   */
61	  addProvider(provider: SecretProvider): void {
62	    this.providers.push(provider);
63	  }
64	
65	  /**
66	   * Resolve a secret reference to its actual value
67	   */
68	  async resolveSecret(secretRef: string): Promise<string> {
69	    if (this.logSecretAccess) {
70	      log.info('Resolving secret', { secretRef });
71	    }
72	
73	    // 1. Check environment variables first (for testing and local dev)
74	    if (this.allowEnvironmentFallback && process.env[secretRef]) {
75	      if (this.logSecretAccess) {
76	        log.info('Found secret in environment', { secretRef });
77	      }
78	      return process.env[secretRef]!;
79	    }
80	
81	    // 2. Try secret providers
82	    for (const provider of this.providers) {
83	      try {
84	        const value = await provider.resolve(secretRef);
85	        if (this.logSecretAccess) {
86	          log.info('Resolved secret via provider', { provider: provider.name, secretRef });
87	        }
88	        return value;
89	      } catch (error) {
90	        if (this.logSecretAccess) {
91	          log.warn('Provider failed to resolve secret', { provider: provider.name, secretRef, error });
92	        }
93	        // Continue to next provider
94	      }
95	    }
96	
97	    throw new Error(`Secret not found for ref: ${secretRef}`);
98	  }
99	
100	  /**
101	   * Resolve all secrets in a data source configuration
102	   */
103	  async resolveCredentials(config: DataSourceCredentials): Promise<DataSourceCredentials> {
104	    const resolved = { ...config };
