1	import { NextRequest } from 'next/server';
2	
3	/**
4	 * Determines if authentication should be bypassed for local development.
5	 * 
6	 * This function provides a consistent way to check if auth should be disabled
7	 * across all apps (dashboard, interface, etc.) to avoid inconsistencies.
8	 * 
9	 * @param req - The Next.js request object (optional, for hostname checking)
10	 * @returns true if auth should be bypassed, false otherwise
11	 */
12	export function shouldDisableAuth(req?: NextRequest | { nextUrl?: { hostname?: string } }): boolean {
13	  // Check environment variable first (explicit override)
14	  if (process.env.DISABLE_DASHBOARD_AUTH === 'true') {
15	    return true;
16	  }
17	
18	  // In development, also check if we're on localhost
19	  if (process.env.NODE_ENV === 'development') {
20	    // Check hostname from request if available
21	    const hostname = req?.nextUrl?.hostname || 
22	                     (typeof window !== 'undefined' ? window.location.hostname : null);
23	    
24	    if (hostname === 'localhost' || hostname === '127.0.0.1') {
25	      return true;
26	    }
27	
28	    // Fallback: check NEXTAUTH_URL
29	    if (process.env.NEXTAUTH_URL?.includes('localhost')) {
30	      return true;
31	    }
32	  }
33	
34	  return false;
35	}
