1	/**
2	 * Shared API authentication helper.
3	 * Routes can call `requireAuth(req)` to enforce either:
4	 *   1. A valid next-auth session (browser cookie), OR
5	 *   2. The `x-shared-secret` header matching MESH_SHARED_SECRET
6	 *
7	 * Returns null if authenticated, or a 401 NextResponse to return early.
8	 */
9	import { NextRequest, NextResponse } from 'next/server';
10	import { getServerSession } from 'next-auth';
11	import { interfaceAuthOptions } from '@interface/lib/auth-config';
12	
13	export async function requireAuth(req: NextRequest): Promise<NextResponse | null> {
14	  // In test mode, bypass authentication (matches middleware.ts and page.tsx behavior)
15	  if (
16	    process.env.TEST_MODE === 'true' ||
17	    process.env.NEXT_PUBLIC_TEST_MODE === 'true' ||
18	    process.env.NEXT_PUBLIC_TEST_ANONYMOUS_USER === 'true'
19	  ) {
20	    return null; // test mode — no auth required
21	  }
22	
23	  // Check shared secret header first (fast path for internal/mesh calls)
24	  const secret = req.headers.get('x-shared-secret');
25	  const meshSecret = process.env.MESH_SHARED_SECRET;
26	  if (meshSecret && secret === meshSecret) {
27	    return null; // authenticated
28	  }
29	
30	  // Check next-auth session (browser cookie path)
31	  try {
32	    const session = await getServerSession(interfaceAuthOptions);
33	    if (session?.user) {
34	      return null; // authenticated
35	    }
36	  } catch {
37	    // Session check failed, fall through to 401
38	  }
39	
40	  return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
41	}
