1	/**
2	 * Screenshot evaluator — generates an HTML report from test results.
3	 */
4	
5	import * as fs from 'fs';
6	import * as path from 'path';
7	
8	export interface ReportEntry {
9	  testName: string;
10	  toolName: string;
11	  passed: boolean;
12	  screenshotPath: string;
13	  httpStatus: number;
14	  consoleErrors: string[];
15	  durationMs: number;
16	  note?: string;
17	}
18	
19	const entries: ReportEntry[] = [];
20	
21	export function addEntry(e: ReportEntry) {
22	  entries.push(e);
23	}
24	
25	export function generateReport(outputPath?: string) {
26	  const reportPath = outputPath ?? path.resolve(__dirname, 'report.html');
27	  const screenshotsDir = path.resolve(__dirname, 'screenshots');
28	
29	  const rows = entries
30	    .map((e) => {
31	      const relScreenshot = path.relative(path.dirname(reportPath), e.screenshotPath);
32	      const statusBadge = e.passed
33	        ? '<span style="color:green;font-weight:bold">✅ PASS</span>'
34	        : '<span style="color:red;font-weight:bold">❌ FAIL</span>';
35	      const errorsHtml = e.consoleErrors.length
36	        ? `<pre style="color:red;font-size:12px;max-height:150px;overflow:auto">${escapeHtml(e.consoleErrors.join('\n'))}</pre>`
37	        : '<span style="color:gray">none</span>';
38	      return `
39	      <tr>
40	        <td>${escapeHtml(e.testName)}</td>
41	        <td><code>${escapeHtml(e.toolName)}</code></td>
42	        <td>${statusBadge}</td>
43	        <td>${e.httpStatus}</td>
44	        <td>${e.durationMs}ms</td>
45	        <td>${errorsHtml}</td>
46	        <td>${e.note ? escapeHtml(e.note) : ''}</td>
47	        <td><a href="${relScreenshot}" target="_blank"><img src="${relScreenshot}" style="max-width:300px;max-height:180px;border:1px solid #ccc" /></a></td>
48	      </tr>`;
49	    })
50	    .join('\n');
