9	test.describe('Core PearlOS Tools', () => {
10	  test.afterAll(() => {
11	    generateReport();
12	  });
13	
14	  test('open notes panel', async ({ page }) => {
15	    const { logs, errors } = setupConsoleCapture(page);
16	    await loadPearlOS(page);
17	    const start = Date.now();
18	
19	    const result = await invokeToolAndScreenshot(
20	      page,
21	      'bot_open_notes',
22	      {},
23	      { label: 'open-notes', consoleLogs: logs, consoleErrors: errors },
24	    );
25	
26	    addEntry({
27	      testName: 'Open Notes',
28	      toolName: 'bot_open_notes',
29	      passed: result.httpStatus === 200 || result.httpStatus === 0,
30	      screenshotPath: result.screenshotPath,
31	      httpStatus: result.httpStatus,
32	      consoleErrors: result.consoleErrors,
33	      durationMs: Date.now() - start,
34	    });
35	
36	    expect(result.screenshot.length).toBeGreaterThan(0);
37	  });
38	
