44	    const result = await invokeToolAndScreenshot(
45	      page,
46	      'bot_create_note',
47	      {
48	        title: 'Test Note from Visual Regression',
49	        content: 'This note was created by the automated visual regression test harness.',
50	      },
51	      { label: 'create-note', consoleLogs: logs, consoleErrors: errors },
52	    );
