63	    });
64	  });
65	
66	  test('open YouTube panel', async ({ page }) => {
67	    const { logs, errors } = setupConsoleCapture(page);
68	    await loadPearlOS(page);
69	    const start = Date.now();
70	
71	    const result = await invokeToolAndScreenshot(
72	      page,
