1	import { createAuthOptions } from '@nia/prism/core/auth/authOptions';
2	import { NextAuthOptions } from 'next-auth';
3	
4	const isProduction = process.env.NODE_ENV === 'production';
5	
6	function tryGetOrigin(urlLike?: string): string | null {
7	  if (!urlLike) return null;
8	  try {
9	    return new URL(urlLike).origin;
10	  } catch {
11	    return null;
12	  }
13	}
14	
15	function resolveInterfaceUrl(): string {
16	  // Prefer tunnel URL over localhost-based env vars when available
17	  const configured =
18	    process.env.NEXT_PUBLIC_TUNNEL_URL ||
19	    process.env.NEXTAUTH_INTERFACE_URL ||
20	    process.env.NEXTAUTH_URL ||
21	    process.env.NEXT_PUBLIC_INTERFACE_URL;
22	
23	  if (configured) return configured;
24	
25	  if (!isProduction) return 'http://localhost:3000';
26	
27	  throw new Error(
28	    'Missing interface base URL configuration. Set NEXTAUTH_INTERFACE_URL (or NEXTAUTH_URL) in production.',
29	  );
30	}
31	
32	// Set the NEXTAUTH_URL for the interface
33	// Prefer tunnel URL so NextAuth's baseUrl in callbacks points to the tunnel, not localhost
34	const defaultUrl = resolveInterfaceUrl();
35	process.env.NEXTAUTH_URL = process.env.NEXT_PUBLIC_TUNNEL_URL || process.env.NEXTAUTH_URL || process.env.NEXTAUTH_INTERFACE_URL || defaultUrl;
36	
37	// Create auth options for interface with app-specific configuration
38	const authConfig = {
39	  appType: 'interface' as const,
40	  baseUrl: process.env.NEXTAUTH_INTERFACE_URL || defaultUrl,
41	  googleCredentials: {
42	    clientId: process.env.GOOGLE_INTERFACE_CLIENT_ID || process.env.GOOGLE_CLIENT_ID!,
43	    clientSecret: process.env.GOOGLE_INTERFACE_CLIENT_SECRET || process.env.GOOGLE_CLIENT_SECRET!,
44	  },
45	  cookiePrefix: 'interface-auth',
46	  pages: {
47	    signIn: '/login',
48	  },
49	  redirectHandler: (url: string, baseUrl: string) => {
50	    // Prefer tunnel URL for redirects (critical for Cloudflare tunnel access)
51	    // Then runtime request origin (baseUrl), then configured env vars
52	    const tunnelOrigin = tryGetOrigin(process.env.NEXT_PUBLIC_TUNNEL_URL);
53	    const runtimeOrigin = tryGetOrigin(baseUrl);
54	    const configuredOrigin =
55	      tryGetOrigin(process.env.NEXT_PUBLIC_INTERFACE_URL) ||
56	      tryGetOrigin(process.env.NEXTAUTH_INTERFACE_URL) ||
57	      tryGetOrigin(process.env.NEXTAUTH_URL) ||
58	      tryGetOrigin(defaultUrl);
59	    // Tunnel origin takes priority so redirects go to the tunnel, not localhost
60	    const effectiveOrigin = tunnelOrigin || runtimeOrigin || configuredOrigin || 'http://localhost:3000';
61	    const interfaceUrl = `${effectiveOrigin}/`;
62	    
63	    try {
64	      // Normalize to an absolute URL for inspection
65	      const current = new URL(url, interfaceUrl);
66	      // If a callbackUrl is provided, prefer it (and keep it same-origin)
67	      const cb = current.searchParams.get('callbackUrl');
68	      if (cb) {
69	        const target = new URL(cb, interfaceUrl);
70	        if (target.origin === effectiveOrigin) {
71	          return target.toString();
72	        }
73	      }
74	      // Avoid landing on raw auth pages; send to interface home when no callback provided
75	      if (current.pathname.includes('/auth/signin') || current.pathname === '/login') {
76	        return interfaceUrl;
77	      }
78	      // Same-origin safe redirect
79	      if (current.origin === effectiveOrigin) {
80	        return current.toString();
81	      }
82	    } catch {
83	      // fall through to default
84	    }
85	    // Default: go home on interface
86	    return interfaceUrl;
87	  }
88	};
89	
90	const baseAuthOptions = createAuthOptions(authConfig);
91	
92	// Interface-specific auth configuration
93	export const interfaceAuthOptions: NextAuthOptions = {
94	  ...baseAuthOptions,
95	};

